@router.patch({{path}}, response_model=ParentRead)
async def patch_parent(parent_id: int, data: ParentPatch) -> Parent:
    """Patch parent."""
    async def write(session: AsyncClientSession) -> Parent:
        """Write."""
        row = await require_parent(parent_id, session)
        changes = _encode(model_values(data, exclude_unset=True))
        if changes:
            changes["updated_at"] = datetime.now(UTC)
            await Parent.get_pymongo_collection().update_one({"_id": row.id}, {"$set": changes}, session=session)
        return await require_parent(row.id, session)
    return await transaction(write)
